using System.Security.Claims;
using Microsoft.AspNetCore.Components.Authorization;
using sv_8b141f240f7b4b72b14f9cf31ed74bc5.Client.Pages;
using sv_8b141f240f7b4b72b14f9cf31ed74bc5.Components;

var builder = WebApplication.CreateBuilder(args);

// Add services to the container.
builder.Services.AddRazorComponents()
    .AddInteractiveServerComponents()
    .AddInteractiveWebAssemblyComponents();

builder.Services.AddAuthorization();
builder.Services.AddCascadingAuthenticationState();
builder.Services.AddScoped<AuthenticationStateProvider, FakeAuthenticationStateProvider>();
builder.Services.AddAuthenticationStateSerialization(options =>
    options.SerializeAllClaims = true);

app.Run();

public class FakeAuthenticationStateProvider : AuthenticationStateProvider
{
    public override Task<AuthenticationState> GetAuthenticationStateAsync()
    {
        var claims = new List<Claim>
        {
            new(ClaimTypes.Name, "bob@example.com"),
            new(ClaimTypes.Email, "bob@example.com"),
            new(ClaimTypes.Role, "User"),
            new(ClaimTypes.Role, "Editor"),
        };

        var identity = new ClaimsIdentity(claims, "FakeAuth");
        var principal = new ClaimsPrincipal(identity);

        return Task.FromResult(new AuthenticationState(principal));
    }
}

using Microsoft.AspNetCore.Components.WebAssembly.Hosting;

var builder = WebAssemblyHostBuilder.CreateDefault(args);

builder.Services.AddAuthorizationCore();
builder.Services.AddAuthenticationStateDeserialization();

await builder.Build().RunAsync();

